\label{p:existii+}
$g$ is convex and lower semicontinuous.
\item 
\label{p:existii}
$C$ is a nonempty convex compact set.
\item 
\label{p:existiii}
Problem~\ref{prob:main} admits at least a solution.
\end{enumerate}
\end{proposition}

